const SIZE=40, milestones=[{id:'first',label:'A place to call home',goal:8,reward:150},{id:'village',label:'A growing village',goal:40,reward:300},{id:'town',label:'Town together',goal:120,reward:700},{id:'city',label:'A real city',goal:300,reward:1500},{id:'metro',label:'Metropolis maker',goal:800,reward:3000}];
function fresh(name){return {version:1,id:typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():String(Date.now()),name:name.trim().slice(0,40)||'New City',money:2000,tiles:Array(SIZE*SIZE).fill(null),trees:Array.from({length:SIZE*SIZE},(_,i)=>((i*7919+17)%101)<14),earned:[],ticks:0,nextPayment:Date.now()+60000,created:Date.now()};}
