function nearby(s,i,predicate,radius=3){let x=i%SIZE,y=Math.floor(i/SIZE);for(let dy=-radius;dy<=radius;dy++)for(let dx=-radius;dx<=radius;dx++){if(!dx&&!dy||Math.abs(dx)+Math.abs(dy)>radius)continue;let a=x+dx,b=y+dy;if(a<0||a>=SIZE||b<0||b>=SIZE)continue;const tile=s.tiles[b*SIZE+a];if(tile&&predicate(catalog[tile.type],tile))return true;}return false;}
function neighborhood(s,i){const b=s.tiles[i];if(!b)return {bonus:0,reason:''};const c=catalog[b.type];if(c.pop&&nearby(s,i,c=>c.green))return {bonus:.15,reason:'Green neighborhood · +15% home tax'};if(c.commerce&&nearby(s,i,c=>c.pop))return {bonus:.2,reason:'Local customers · +20% business tax'};return {bonus:0,reason:c.pop?'Add green space within 3 tiles for +15% home tax.':c.commerce?'Build near homes (within 3 tiles) for +20% business tax.':''};}
function stats(s){let pop=0,income=120,expense=0,jobs=0,parks=0,pollution=0,roads=0,connected=0,count=0,neighborhoodBonus=0,festivalBonus=0;let capacities={education:0,health:0,safety:0,power:24,water:24,transport:0,culture:0};s.tiles.forEach((b,i)=>{if(!b)return;const c=catalog[b.type],m=b.level;if(b.type==='road'){roads+=m===2?1:0;return;}count++;const access=adjacent(s,i);if(access)connected++;pop+=(c.pop||0)*m;jobs+=(c.jobs||0)*m;const base=(c.income||0)*m*(access?1:.5),bonus=Math.round(base*neighborhood(s,i).bonus);income+=Math.round(base)+bonus;neighborhoodBonus+=bonus;expense+=(c.expense||0)*m;if(c.service)capacities[c.service]+=c.capacity*m;parks+=(c.happy||0)*m;if(b.type==='stadium')festivalBonus+=100*m;if(b.type==='factory'){let x=i%SIZE,y=Math.floor(i/SIZE);for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){let a=x+dx,b=y+dy;if(a<0||a>=SIZE||b<0||b>=SIZE||Math.abs(dx)+Math.abs(dy)>4)continue;let home=s.tiles[b*SIZE+a];if(home&&catalog[home.type].pop)pollution+=3*m;}}});
const coverage=k=>pop?Math.min(1,capacities[k]/pop):1;const extra=(pop&&capacities.transport?coverage('transport')*4:0)+(pop&&capacities.culture?coverage('culture')*4:0);const happiness=Math.round(Math.max(15,Math.min(100,55+parks+roads*.3+coverage('education')*8+coverage('health')*8+coverage('safety')*5+extra-(1-coverage('power'))*18-(1-coverage('water'))*18-pollution-(count-connected)*1.5)));
income=Math.round(income*(.75+happiness/200))+(s.tradeIncome||0);let level=pop>=300?4:pop>=100?3:pop>=32?2:1;return {pop,income,expense,net:income-expense,happiness,level,jobs,capacities,coverage,connected,count,neighborhoodBonus,festivalBonus};}
function build(s,type,i){const c=catalog[type];if(!c||!Number.isInteger(i)||i<0||i>=s.tiles.length)return 'Choose a tile inside the map.';if(s.tiles[i])return 'This tile is occupied. Select it to inspect.';if((c.unlock||1)>stats(s).level)return `Unlocks at city level ${c.unlock}.`;if(s.money<c.cost)return 'A little short on funds. Your next payment is on its way.';s.money-=c.cost;s.tiles[i]={type,level:1};s.trees[i]=false;return null;}
function upgradeCost(b){return Math.round(catalog[b.type].cost*.8*b.level);}
function upgrade(s,i){let b=s.tiles[i];if(!b)return 'Select a building.';if(b.level>=(b.type==='road'?2:3))return 'Already at maximum level.';let cost=upgradeCost(b);if(s.money<cost)return 'Save a little more for this upgrade.';s.money-=cost;b.level++;return null;}
