function tick(s,now=Date.now()){if(now<s.nextPayment)return [];let notices=[];let turns=Math.min(10,Math.floor((now-s.nextPayment)/60000)+1);for(let n=0;n<turns;n++){let a=stats(s);let grant=Math.max(0,80-a.net);s.money+=a.net+grant;s.ticks++;if(grant)notices.push(`Town support added $${grant} to keep building possible.`);if(s.ticks%4===0){let bonus=100+Math.round(a.pop*.5)+a.festivalBonus;s.money+=bonus;notices.push(`Market day! Local visitors brought $${bonus}.`);}for(let m of milestones)if(a.pop>=m.goal&&!s.earned.includes(m.id)){s.earned.push(m.id);s.money+=m.reward;notices.push(`${m.label}: $${m.reward} milestone grant!`);}}s.nextPayment=now+60000;return notices;}
