function progress(w){let a=summary(w),before=w.level;if(a.population>=32)w.level=Math.max(2,w.level);if(a.population>=120&&a.cities>=3)w.level=3;return w.level>before?`Level ${w.level} unlocked — ${w.level===2?'name your country and found more cities':'name your continent and create more countries'}!`:null;}
function recalculate(w){let list=cities(w);for(let city of list)city.tradeIncome=w.connections.filter(l=>l.a===city.id||l.b===city.id).length*15;}
function addCity(w,countryId,cityName){progress(w);if(w.level<2)throw Error('Reach 32 residents to unlock your country.');if(cities(w).length>=24)throw Error('This world has reached its 24-city capacity.');let country=w.countries.find(c=>c.id===countryId);if(!country)throw Error('Choose a country.');if(country.cities.length>=12)throw Error('A country can hold up to 12 cities.');let city=E.fresh(name(cityName,'New City'));country.cities.push(city);w.activeCityId=city.id;return city;}
function addCountry(w,countryName,cityName){progress(w);if(w.level<3)throw Error('Reach 120 total residents across at least 3 cities to unlock your continent.');if(w.countries.length>=8||cities(w).length>=24)throw Error('Your continent is full (8 countries / 24 cities).');let country={id:uid(),name:name(countryName,'New Country'),cities:[E.fresh(name(cityName,'First City'))]};w.countries.push(country);w.activeCityId=country.cities[0].id;return country;}
