function tick(w,now=Date.now()){recalculate(w);let messages=[];for(let city of cities(w)){let events=E.tick(city,now);if(city.id===w.activeCityId)messages.push(...events);}let unlocked=progress(w);if(unlocked)messages.push(unlocked);return messages;}
